INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001310011','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001310011","revision":1,"targetId":"80000000-0000-4000-8000-000000013101","prompt":"Die Nacharbeit kostete das Team zwei zusätzliche Stunden. Warum musste es länger arbeiten?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The team had to fix something previously done incorrectly.","de":"Das Team musste eine fehlerhafte Arbeit verbessern."},"options":[{"id":"0","text":"Ein früherer Fehler musste korrigiert werden."},{"id":"1","text":"Es gab eine neue Firmenfeier."},{"id":"2","text":"Die Arbeitszeit wurde verkürzt."},{"id":"3","text":"Der Kunde hatte bereits bezahlt."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It was extra corrective work.","de":"Es war zusätzliche Arbeit zur Korrektur eines Fehlers."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen eines Fehlers musste das Team zwei Stunden nacharbeiten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1630 (43aa8f0056bbc360c50eac8b3ec06738db408e28b90186766c308b6d9b867f63), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
