INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001310031','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001310031","revision":1,"targetId":"80000000-0000-4000-8000-000000013103","prompt":"Wegen der hohen Nachfrage sind alle Beratungstermine ausgebucht. Was ist passiert?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Appointments fill because many people want the service.","de":"Viele Personen möchten einen Termin vereinbaren."},"options":[{"id":"0","text":"Viele Menschen interessieren sich für das Angebot."},{"id":"1","text":"Niemand möchte die Leistung nutzen."},{"id":"2","text":"Die Firma hat alle Mitarbeitenden entlassen."},{"id":"3","text":"Der Preis wurde gesetzlich festgelegt."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Demand is high.","de":"Viele Menschen fragen die Leistung nach."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Viele Interessierte haben bereits alle Beratungstermine gebucht.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1634 (f67a1a312aa36941a7b849a05a2b54374669187feb4a6027e1f29dafb22f016b), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
