INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001310040','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001310040","revision":1,"targetId":"80000000-0000-4000-8000-000000013104","prompt":"Die Firma setzt auf ___ und verwendet langlebige, reparierbare Materialien.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The company aims to conserve resources over time.","de":"Das Unternehmen möchte Ressourcen langfristig schonen."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Nachhaltigkeit"},{"id":"1","text":"Verspätung"},{"id":"2","text":"Überstunden"},{"id":"3","text":"Kündigung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Nachhaltigkeit is long-term responsible use of resources.","de":"Nachhaltigkeit bedeutet unter anderem einen schonenden Umgang mit Ressourcen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma setzt auf Nachhaltigkeit und verwendet langlebige, reparierbare Materialien.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1635 (f38f5c3b92f8a45bc045fd45fe3b98edee0a4c1815e54a44740bbc0ad5feda2e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
